import torch
K = [2, 2, 2]
S = [2, 2, 2]
P = [0, 0, 0]

def _out_shape(shape):
    return [shape[0], shape[1]] + [(shape[i + 2] + 2 * P[i] - K[i]) // S[i] + 1 for i in range(3)]

def run(grad_output, self_input, kernel_size, stride, padding, ceil_mode, count_include_pad, divisor_override):
    return torch.ops.aten.avg_pool3d_backward(grad_output, self_input, kernel_size, stride, padding, ceil_mode, count_include_pad, divisor_override)
